def _generate_easy_extras() -> list[tuple]:
    """Generate additional easy questions from templates."""
    extras = []
    # Valid universal instantiation variants
    for cat_a, cat_b, member, article in _EASY_TEMPLATES_VALID_UI:
        q = f"All {cat_a} are {cat_b}. {member} is {article} {cat_a[:-1] if cat_a.endswith('s') else cat_a}. Therefore, {member} is {article} {cat_b[:-1] if cat_b.endswith('s') else cat_b}. Is this argument valid?"
        extras.append((
            q,
            ["Valid", "Invalid", "Contradictory", "Uncertain"],
            "Valid",
            f"Universal instantiation: {member} belongs to the {cat_a} category, and all {cat_a} are {cat_b}.",
            ["valid arguments", "universal instantiation"],
        ))

    # Invalid affirming the consequent variants
    for cat_a, prop_b, individual_stmt, alt_exp in _EASY_TEMPLATES_INVALID_AC:
        q = f"All {cat_a} are {prop_b}. {individual_stmt}. Therefore, {individual_stmt.split(' ')[0]} is {('an ' if cat_a[0] in 'aeiou' else 'a ')}{cat_a[:-1] if cat_a.endswith('s') else cat_a}. Is this valid?"
        extras.append((
            q,
            ["Valid", "Invalid", "Sound", "True"],
            "Invalid",
            f"Affirming the consequent — being {prop_b} doesn't guarantee being {('an ' if cat_a[0] in 'aeiou' else 'a ')}{cat_a[:-1] if cat_a.endswith('s') else cat_a}. {alt_exp}",
            ["invalid arguments", "affirming the consequent"],
        ))

    return extras


def _generate_medium_extras() -> list[tuple]:
    """Generate additional medium questions from templates."""
    extras = []
    # Modus tollens variants
    for condition, consequence, neg_cons, conclusion in _MEDIUM_TEMPLATES_MT:
        q = f"If {condition}, {consequence}. {neg_cons}. Therefore, {conclusion}. Is this valid?"
        extras.append((
            q,
            ["Valid", "Invalid", "Sound", "Uncertain"],
            "Valid",
            f"Modus tollens: {condition} → {consequence}. {neg_cons} (negation of consequence). Therefore, {conclusion}.",
            ["valid arguments", "modus tollens"],
        ))

    # Affirming the consequent (invalid) variants
    for cat_a, prop_b, individual_stmt, alt_exp in _MEDIUM_TEMPLATES_AC_INVALID:
        q = f"All {cat_a} {prop_b}. {individual_stmt}. Therefore, {individual_stmt.split(' ')[0]} is one of the {cat_a}. Is this valid?"
        extras.append((
            q,
            ["Valid", "Invalid", "Sound", "True"],
            "Invalid",
            f"Affirming the consequent — {alt_exp}",
            ["invalid arguments", "affirming the consequent"],
        ))

    return extras


def _generate_hard_extras() -> list[tuple]:
    """Generate additional hard questions from templates."""
    extras = []
    # Chain reasoning (valid)
    for a_b, b_c, c_d, individual, conclusion in _HARD_TEMPLATES_CHAIN:
        q = f"{a_b}. {b_c}. {c_d}. {individual}. Therefore, {conclusion}. Is this valid?"
        extras.append((
            q,
            ["Valid", "Invalid", "Sound", "Uncertain"],
            "Valid",
            f"Extended transitive chain: each premise links to the next, and the individual satisfies the first condition, so the final conclusion follows.",
            ["valid arguments", "extended chain"],
        ))

    # Contradiction detection
    for s1, s2, s3, s4, explanation in _HARD_TEMPLATES_CONTRADICTION:
        q = f"Statement set: (1) {s1}. (2) {s2}. (3) {s3}. (4) {s4}. These statements are:"
        extras.append((
            q,
            ["Consistent", "Contradictory", "Valid", "Sound"],
            "Contradictory",
            explanation,
            ["contradictions", "complex inconsistency"],
        ))

    return extras


def build() -> list[dict]:
    questions: list[dict] = []
    id_counter = 1

    # Combine hand-written and generated questions
    easy_all = list(EASY) + _generate_easy_extras()
    medium_all = list(MEDIUM) + _generate_medium_extras()
    hard_all = list(HARD) + _generate_hard_extras()

    # Trim to exactly 200 per difficulty
    easy_all = easy_all[:200]
    medium_all = medium_all[:200]
    hard_all = hard_all[:200]

    for difficulty, items in [("Easy", easy_all), ("Medium", medium_all), ("Hard", hard_all)]:
        for q, choices, answer, explanation, tags in items:
            questions.append(
                {
                    "id": id_counter,
                    **B,
                    "difficulty": difficulty,
                    "question": q,
                    "choices": choices,
                    "answer": answer,
                    "explanation": explanation,
                    "tags": ["symbolic logic", "truth and validity"] + tags,
                }
            )
            id_counter += 1

    return questions


if __name__ == "__main__":
    data = build()
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    easy = sum(1 for q in data if q["difficulty"] == "Easy")
    medium = sum(1 for q in data if q["difficulty"] == "Medium")
    hard = sum(1 for q in data if q["difficulty"] == "Hard")
    print(f"Generated {len(data)} questions → {OUTPUT}")
    print(f"  Easy: {easy} | Medium: {medium} | Hard: {hard}")
